#!/usr/bin/env node

/**
 * Export changelog entries to harvous.com/data/webflow-changelog.csv
 *
 * Replaces the retired Webflow API sync. Reads Changelog/{version}.md files
 * (generated by bump-version.js) and appends CSV rows in the Webflow export
 * format expected by harvous.com/src/lib/release-notes-data.ts.
 *
 * Usage:
 *   node scripts/export-changelog-csv.js [--version 1.217.231] [--backfill] [--csv path]
 *
 * Backfill exports changelog files at or above the CSV's max version number,
 * then skips rows already present (version+title fingerprint). Using >= instead
 * of > handles semver resets where legacy CSV rows share the same version.
 *
 * Env:
 *   HARVOUS_COM_CSV_PATH — override output CSV path
 */

import { createHash, randomBytes } from "crypto";
import { existsSync, readFileSync, readdirSync, writeFileSync } from "fs";
import { basename, join } from "path";
import { fileURLToPath } from "url";
import { dirname } from "path";

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);

const COLLECTION_ID = "6914bfd8c7facb8fa00eaad3";
const LOCALE_ID = "68feb1d1933e97605f97913b";
const CSV_HEADER =
  "Name,Slug,Collection ID,Locale ID,Item ID,Archived,Draft,Created On,Updated On,Published On,Version Number,Date,Commit Message,Category";

const SECTION_CATEGORY = {
  features: "Feature",
  fixes: "Fix",
  improvements: "Improvement",
  "breaking changes": "Feature",
  performance: "Improvement",
};

/**
 * Sections that stay in the developer changelog and never reach harvous.com.
 *
 * An unrecognised section is NOT skipped — it falls through to `inferCategoryFromLine` and
 * publishes. So this is the only way to write something down for developers without telling
 * users about it, and it needs to hold every heading meant to stay in.
 *
 * "Internal" was added after a CI change published the line "We've fixed an issue: Sync release
 * notes with a deploy key instead of an expiring token" to the public feed. Filing it under a
 * heading that merely wasn't in SECTION_CATEGORY did nothing.
 *
 * Better still, infrastructure work should be committed as `chore:`, which bump-version.js does
 * not bump — then no changelog file is generated at all.
 */
const PRIVATE_SECTIONS = new Set([
  "documentation",
  "internal",
  "chore",
  "ci",
  "build",
  // generate-changelog.js's catch-all bucket for every commit type that isn't
  // feat/fix/improvement/perf/docs — so `chore:`, `test:`, `ci:`, `refactor:`, `style:`. None of
  // those describe something a reader can see. It published "Stop tracking Playwright run
  // artifacts" and "Fail the build when a marquee label renders zero pixels wide" before it was
  // added here.
  "other changes",
]);

function resolveCsvPath(cliPath) {
  if (cliPath) return cliPath;
  if (process.env.HARVOUS_COM_CSV_PATH) return process.env.HARVOUS_COM_CSV_PATH;
  const sibling = join(__dirname, "../../harvous.com/data/webflow-changelog.csv");
  if (existsSync(sibling)) return sibling;
  return null;
}

function compareSemver(a, b) {
  const pa = a.split(".").map(Number);
  const pb = b.split(".").map(Number);
  const len = Math.max(pa.length, pb.length);
  for (let i = 0; i < len; i++) {
    const diff = (pa[i] ?? 0) - (pb[i] ?? 0);
    if (diff !== 0) return diff;
  }
  return 0;
}

function escapeCsvField(value) {
  const str = String(value ?? "");
  if (/[",\n\r]/.test(str)) return `"${str.replace(/"/g, '""')}"`;
  return str;
}

function formatWebflowDate(date) {
  const d = new Date(date);
  const days = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
  const months = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
  const pad = (n) => String(n).padStart(2, "0");
  return `${days[d.getUTCDay()]} ${months[d.getUTCMonth()]} ${pad(d.getUTCDate())} ${d.getUTCFullYear()} ${pad(d.getUTCHours())}:${pad(d.getUTCMinutes())}:${pad(d.getUTCSeconds())} GMT+0000 (Coordinated Universal Time)`;
}

/**
 * No prose prefix any more.
 *
 * This used to return "We've added a new feature: ", "We've fixed an issue: " or "We've made an
 * improvement: " to open the published description. Two things were wrong with it.
 *
 * It duplicated the row: every entry already carries a `Category` column with exactly that
 * classification, so the sentence restated in prose what the field next to it already said.
 *
 * Worse, it asserted a shape the subject often did not have. "We've added a new feature: $6/mo
 * and $36/yr, and the founding discount retired" published a price *cut* as an addition, and
 * "We've fixed an issue: The font control says what it changes, and where" reads as a bug
 * report about a sentence that is describing the new label. The prefix was chosen from the
 * commit type, which says how the change was committed, not what happened to the reader.
 *
 * The description is now the subject alone. Still a commit subject — the honest fix for that is
 * a human or /marketing-agent rewriting the row, which is why these export as `Draft: true`.
 */

function capitalizeFirst(text) {
  if (!text) return text;
  return text.charAt(0).toUpperCase() + text.slice(1);
}

function createSlug(name, version, index) {
  const base = name
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .slice(0, 40)
    .replace(/^-+|-+$/g, "");
  const hash = createHash("sha1").update(`${version}:${index}:${name}`).digest("hex").slice(0, 7);
  return `${base}-${hash}`;
}

function buildCommitMessageHtml(title) {
  const line = capitalizeFirst(title.replace(/^-\s*/, "").trim());
  return `<p>${line}</p>`;
}

function inferCategoryFromLine(line) {
  const trimmed = line.trim();
  const lower = trimmed.toLowerCase();
  if (lower.startsWith("fix ") || /^fix\b/i.test(trimmed)) return "Fix";
  if (lower.startsWith("add ") || lower.startsWith("feat")) return "Feature";
  return "Improvement";
}

function parseChangelogMarkdown(content, version) {
  const dateMatch = content.match(/\*\*Release Date\*\*:\s*(.+)/i);
  const releaseDate = dateMatch ? Date.parse(dateMatch[1].trim()) : Date.now();
  const date = Number.isNaN(releaseDate) ? new Date() : new Date(releaseDate);

  const items = [];
  const lines = content.split("\n");
  let currentSection = null;

  for (const line of lines) {
    const heading = line.match(/^##\s+(.+)/);
    if (heading) {
      currentSection = heading[1].trim().toLowerCase();
      continue;
    }

    const bullet = line.match(/^-\s+(.+)/);
    if (!bullet || !currentSection) continue;

    const title = bullet[1].trim();
    if (!title || title.length < 4) continue;
    if (PRIVATE_SECTIONS.has(currentSection)) continue;

    let category = SECTION_CATEGORY[currentSection];
    if (!category) {
      category = inferCategoryFromLine(title);
    }

    items.push({ title: capitalizeFirst(title), category });
  }

  return { version, date, items };
}

function rowFingerprint(version, title) {
  return `${version}\n${title.toLowerCase().trim()}`;
}

function loadExistingFingerprints(csvText) {
  const rows = parseCsvRows(csvText);
  const headers = rows[0] ?? [];
  const versionIdx = headers.indexOf("Version Number");
  const nameIdx = headers.indexOf("Name");
  const seen = new Set();

  for (const values of rows.slice(1)) {
    const version = values[versionIdx]?.trim();
    const name = values[nameIdx]?.trim();
    if (version && name) seen.add(rowFingerprint(version, name));
  }

  return seen;
}

function maxVersionInCsv(csvText) {
  const rows = parseCsvRows(csvText);
  const headers = rows[0] ?? [];
  const versionIdx = headers.indexOf("Version Number");
  let max = "0.0.0";

  for (const values of rows.slice(1)) {
    const version = values[versionIdx]?.trim();
    if (version && /^\d+\.\d+\.\d+/.test(version) && compareSemver(version, max) > 0) {
      max = version;
    }
  }

  return max;
}

function parseCsvRows(text) {
  const rows = [];
  let row = [];
  let field = "";
  let inQuotes = false;

  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    const next = text[i + 1];

    if (inQuotes) {
      if (ch === '"' && next === '"') {
        field += '"';
        i++;
      } else if (ch === '"') {
        inQuotes = false;
      } else {
        field += ch;
      }
      continue;
    }

    if (ch === '"') {
      inQuotes = true;
    } else if (ch === ",") {
      row.push(field);
      field = "";
    } else if (ch === "\n" || (ch === "\r" && next === "\n")) {
      row.push(field);
      field = "";
      if (row.some((c) => c.trim())) rows.push(row);
      row = [];
      if (ch === "\r") i++;
    } else if (ch !== "\r") {
      field += ch;
    }
  }

  if (field.length || row.length) {
    row.push(field);
    if (row.some((c) => c.trim())) rows.push(row);
  }

  return rows;
}

function buildCsvRow({ title, slug, version, date, category }) {
  const webflowDate = formatWebflowDate(date);
  const html = buildCommitMessageHtml(title);
  const itemId = randomBytes(12).toString("hex");

  return [
    escapeCsvField(title),
    slug,
    COLLECTION_ID,
    LOCALE_ID,
    itemId,
    "false",
    "true",
    webflowDate,
    webflowDate,
    "",
    version,
    webflowDate,
    escapeCsvField(html),
    category,
  ].join(",");
}

function changelogRowsFromFile(filepath) {
  const version = basename(filepath, ".md");
  if (!/^\d+\.\d+\.\d+/.test(version)) return [];
  const content = readFileSync(filepath, "utf-8");
  const parsed = parseChangelogMarkdown(content, version);
  return parsed.items.map((item, index) => ({
    version: parsed.version,
    date: parsed.date,
    title: item.title,
    category: item.category,
    slug: createSlug(item.title, parsed.version, index),
  }));
}

function listChangelogFiles(changelogDir) {
  if (!existsSync(changelogDir)) return [];
  return readdirSync(changelogDir)
    .filter((name) => /^\d+\.\d+\.\d+\.md$/.test(name))
    .map((name) => join(changelogDir, name))
    .sort((a, b) => compareSemver(basename(a, ".md"), basename(b, ".md")));
}

/**
 * Export one or more versions to the marketing-site CSV.
 * @returns {{ added: number, csvPath: string | null }}
 */
export function exportChangelogToMarketingSite(options = {}) {
  const {
    version = null,
    backfill = false,
    csvPath = resolveCsvPath(options.csvPath),
    quiet = false,
  } = options;

  if (!csvPath) {
    if (!quiet) {
      console.log("ℹ️  Marketing CSV not found (set HARVOUS_COM_CSV_PATH or use --csv). Skipping export.");
    }
    return { added: 0, csvPath: null };
  }

  const changelogDir = join(__dirname, "..", "Changelog");
  const csvText = readFileSync(csvPath, "utf-8").trimEnd();
  const seen = loadExistingFingerprints(csvText);
  const minVersion = backfill ? maxVersionInCsv(csvText) : null;

  const files = listChangelogFiles(changelogDir).filter((filepath) => {
    const v = basename(filepath, ".md");
    if (version) return v === version;
    // >= so a new Changelog/2.0.3.md still exports when legacy 2.0.3 rows exist in CSV.
    if (backfill && minVersion) return compareSemver(v, minVersion) >= 0;
    return false;
  });

  if (files.length === 0) {
    if (!quiet) console.log("ℹ️  No changelog files to export.");
    return { added: 0, csvPath };
  }

  const newLines = [];

  for (const filepath of files.sort((a, b) => compareSemver(basename(a, ".md"), basename(b, ".md")))) {
    const rows = changelogRowsFromFile(filepath);
    for (const row of rows) {
      const fp = rowFingerprint(row.version, row.title);
      if (seen.has(fp)) continue;
      seen.add(fp);
      newLines.push(buildCsvRow(row));
    }
  }

  if (newLines.length === 0) {
    if (!quiet) console.log("ℹ️  CSV already up to date.");
    return { added: 0, csvPath };
  }

  const output = `${csvText}\n${newLines.join("\n")}\n`;
  writeFileSync(csvPath, output, "utf-8");

  if (!quiet) {
    console.log(`✅ Exported ${newLines.length} release note row(s) → ${csvPath}`);
  }

  return { added: newLines.length, csvPath };
}

function parseArgs(argv) {
  const args = { backfill: false, version: null, csvPath: null };
  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];
    if (arg === "--backfill") args.backfill = true;
    else if (arg === "--version") args.version = argv[++i];
    else if (arg === "--csv") args.csvPath = argv[++i];
  }
  return args;
}

const isMainModule =
  import.meta.url === `file://${process.argv[1]}` || process.argv[1]?.endsWith("export-changelog-csv.js");

if (isMainModule) {
  const args = parseArgs(process.argv.slice(2));
  if (!args.version && !args.backfill) {
    const packageJson = JSON.parse(readFileSync(join(__dirname, "..", "package.json"), "utf-8"));
    args.version = packageJson.version;
  }
  exportChangelogToMarketingSite(args);
}
